import java.util.*;
import java.io.*;

public class p1096g_v3 {
    static final long MOD = 998244353;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        long[] base = new long[10];
        for (int i = 0; i < k; i++) {
            base[sc.nextInt()] = 1;
        }
        long[] res = fastPow(base, n / 2);
        long ans = 0;
        for (long x : res) {
            ans = (ans + x * x) % MOD;
        }
        System.out.println(ans);
    }

    static long[] fastPow(long[] base, long exp) {
        if (exp == 1) return base;
        if ((exp & 1) == 1) {
            return FFT.multiplyPrecise(base, fastPow(base, exp - 1));
        }
        long[] half = fastPow(base, exp >> 1);
        return FFT.multiplyPrecise(half, half);
    }

    static class FFT {
        static final int MAX_K = 21;
        static final int MAX_N = 1 << MAX_K;
        static double[] wR = new double[MAX_N];
        static double[] wI = new double[MAX_N];
        static double[] aR = new double[MAX_N];
        static double[] aI = new double[MAX_N];
        static int n, k, lastK = -1;
        static int[] rev = new int[MAX_N];

        static void transform(boolean inv) {
            if (lastK != k) {
                lastK = k;
                rev[0] = 0;
                for (int i = 1, g = 0; i < n; i++) {
                    if ((i & (i - 1)) == 0) g++;
                    rev[i] = rev[i ^ (1 << g)] ^ (1 << (k - 1 - g));
                }
                wR[1] = 1;
                wI[1] = 0;
                for (int t = 0; t < k - 1; t++) {
                    double angle = Math.PI / n * (1 << (k - 1 - t));
                    double c = Math.cos(angle);
                    double s = Math.sin(angle);
                    int p2 = 1 << t;
                    int p3 = p2 << 1;
                    for (int j = p2, idx = p3; j < p3; j++, idx += 2) {
                        wR[idx] = wR[j];
                        wI[idx] = wI[j];
                        wR[idx + 1] = wR[j] * c - wI[j] * s;
                        wI[idx + 1] = wR[j] * s + wI[j] * c;
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                int r = rev[i];
                if (i < r) {
                    double t = aR[i];
                    aR[i] = aR[r];
                    aR[r] = t;
                    t = aI[i];
                    aI[i] = aI[r];
                    aI[r] = t;
                }
            }
            if (inv) {
                for (int i = 0; i < n; i++) aI[i] = -aI[i];
            }
            for (int len = 1; len < n; len <<= 1) {
                for (int i = 0; i < n; i += len) {
                    int wIdx = len;
                    for (int j = i + len, it = 0; it < len; it++, i++, j++) {
                        double tr = aR[j] * wR[wIdx] - aI[j] * wI[wIdx];
                        double ti = aR[j] * wI[wIdx] + aI[j] * wR[wIdx];
                        wIdx++;
                        aR[j] = aR[i] - tr;
                        aI[j] = aI[i] - ti;
                        aR[i] += tr;
                        aI[i] += ti;
                    }
                }
            }
        }

        static long[] multiply(long[] a, long[] b) {
            int la = a.length, lb = b.length;
            for (k = 0, n = 1; n < la + lb - 1; n <<= 1, k++) {}
            for (int i = 0; i < n; i++) {
                aR[i] = (i < la) ? a[i] : 0;
                aI[i] = (i < lb) ? b[i] : 0;
            }
            transform(false);
            aR[n] = aR[0];
            aI[n] = aI[0];
            double scale = -1.0 / n / 4.0;
            for (int i = 0; i <= n - i; i++) {
                double r1 = aR[i] * aR[i] - aI[i] * aI[i];
                double i1 = 2 * aR[i] * aI[i];
                double r2 = aR[n - i] * aR[n - i] - aI[n - i] * aI[n - i];
                double i2 = -2 * aR[n - i] * aI[n - i];
                double nr = -i1 + i2;
                double ni = r1 - r2;
                aR[i] = nr * scale;
                aI[i] = ni * scale;
                aR[n - i] = aR[i];
                aI[n - i] = -aI[i];
            }
            transform(true);
            long[] res = new long[la + lb - 1];
            for (int i = 0; i < res.length; i++) {
                res[i] = Math.round(aR[i]) % MOD;
            }
            return res;
        }

        static long[] multiplyPrecise(long[] a, long[] b) {
            long sqrtMod = (long) Math.sqrt(MOD);
            long[] al = new long[a.length], ah = new long[a.length];
            long[] bl = new long[b.length], bh = new long[b.length];
            for (int i = 0; i < a.length; i++) {
                al[i] = a[i] % sqrtMod;
                ah[i] = a[i] / sqrtMod;
            }
            for (int i = 0; i < b.length; i++) {
                bl[i] = b[i] % sqrtMod;
                bh[i] = b[i] / sqrtMod;
            }
            long[] r11 = multiply(al, bl);
            long[] r12 = multiply(al, bh);
            long[] r21 = multiply(ah, bl);
            long[] r22 = multiply(ah, bh);
            long[] res = new long[r11.length];
            for (int i = 0; i < res.length; i++) {
                long t1 = (sqrtMod * sqrtMod % MOD) * r22[i] % MOD;
                long t2 = sqrtMod * ((r12[i] + r21[i]) % MOD) % MOD;
                res[i] = (t1 + t2 + r11[i]) % MOD;
            }
            return res;
        }
    }
}
